import crypto from 'node:crypto'
import fs from 'node:fs'
import fsp from 'node:fs/promises'
import path from 'node:path'
import { Readable } from 'node:stream'
import { pipeline } from 'node:stream/promises'
import type { ReadableStream as WebReadableStream } from 'node:stream/web'
import { eq } from 'drizzle-orm'

import { db } from '#/db'
import { bookFiles, books } from '#/db/schema'
import { resolveInside, sortKey } from '#/lib/books'
import { config } from '#/lib/config'
import { readEpub } from '#/lib/epub'
import type { EpubCover } from '#/lib/epub'

export type ScanResult = {
  added: number
  updated: number
  moved: number
  missing: number
  failed: number
  error?: string
}

type DiskFile = { rel: string; abs: string; size: number; mtimeMs: number }
type FileOutcome = 'unchanged' | 'added' | 'updated' | 'moved' | 'failed'

// Scans and imports run one at a time. The state lives on globalThis because the
// Nitro startup plugin and the SSR bundle each get their own copy of this module.
const state = ((
  globalThis as typeof globalThis & {
    bookserveScanner?: {
      tail: Promise<unknown>
      scan: Promise<ScanResult> | null
    }
  }
).bookserveScanner ??= { tail: Promise.resolve(), scan: null })

function serialize<T>(task: () => Promise<T>) {
  const run = state.tail.then(task)
  state.tail = run.catch(() => {})
  return run
}

// Full library scan. A call while a scan is running joins that scan.
export function scanLibrary() {
  state.scan ??= serialize(fullScan).finally(() => {
    state.scan = null
  })
  return state.scan
}

async function fullScan(): Promise<ScanResult> {
  const result: ScanResult = {
    added: 0,
    updated: 0,
    moved: 0,
    missing: 0,
    failed: 0,
  }
  const started = Date.now()
  const root = config.libraryDir

  // If the library itself is gone (e.g. an unmounted NAS share), touch nothing.
  try {
    await fsp.readdir(root)
  } catch (err) {
    result.error = `Library directory is not readable: ${root}`
    console.error(`[scan] ${result.error}`, err)
    return result
  }

  const { files, complete } = await walk(root)
  const onDisk = new Set(files.map((f) => f.rel))
  const seenBookIds = new Set<string>()

  for (const file of files) {
    try {
      const outcome = await importDiskFile(file, (rel) => onDisk.has(rel))
      if (outcome.bookId) seenBookIds.add(outcome.bookId)
      if (outcome.result !== 'unchanged') result[outcome.result]++
    } catch (err) {
      result.failed++
      console.error(`[scan] Failed to import ${file.rel}:`, err)
    }
    // Let requests through between files.
    await new Promise((resolve) => setImmediate(resolve))
  }

  // Books whose files all vanished are flagged, never deleted. Skip this if part
  // of the tree could not be read, so an I/O error doesn't hide books.
  if (complete) {
    const rows = db
      .select({ id: books.id, missing: books.missing })
      .from(books)
      .all()
    db.transaction((tx) => {
      for (const row of rows) {
        const missing = !seenBookIds.has(row.id)
        if (missing === row.missing) continue
        tx.update(books).set({ missing }).where(eq(books.id, row.id)).run()
        if (missing) result.missing++
      }
    })
  }

  console.log(
    `[scan] Done in ${Date.now() - started}ms: ${files.length} files, ` +
      `${result.added} added, ${result.updated} updated, ${result.moved} moved, ` +
      `${result.missing} newly missing, ${result.failed} failed`,
  )
  return result
}

// Recursively lists .epub files. Hidden entries (e.g. macOS ._ files) are skipped.
async function walk(root: string) {
  const files: DiskFile[] = []
  let complete = true
  const visit = async (dir: string) => {
    let entries: fs.Dirent[]
    try {
      entries = await fsp.readdir(dir, { withFileTypes: true })
    } catch (err) {
      complete = false
      console.error(`[scan] Cannot read ${dir}:`, err)
      return
    }
    for (const entry of entries) {
      if (entry.name.startsWith('.')) continue
      const abs = path.join(dir, entry.name)
      if (entry.isDirectory()) {
        await visit(abs)
      } else if (entry.isFile() && /\.epub$/i.test(entry.name)) {
        try {
          const stat = await fsp.stat(abs)
          files.push({
            rel: path.relative(root, abs).split(path.sep).join('/'),
            abs,
            size: stat.size,
            mtimeMs: Math.trunc(stat.mtimeMs),
          })
        } catch (err) {
          complete = false
          console.error(`[scan] Cannot stat ${abs}:`, err)
        }
      }
    }
  }
  await visit(root)
  return { files, complete }
}

// Reconciles one file on disk with the DB. `onDisk` tells whether a stored path
// still exists, to recognize a known file (by hash) that was moved here.
async function importDiskFile(
  file: DiskFile,
  onDisk: (rel: string) => boolean,
): Promise<{ result: FileOutcome; bookId?: string }> {
  const existing = db
    .select()
    .from(bookFiles)
    .where(eq(bookFiles.path, file.rel))
    .get()
  if (
    existing &&
    existing.size === file.size &&
    existing.mtimeMs === file.mtimeMs
  ) {
    return { result: 'unchanged', bookId: existing.bookId }
  }

  const data = await fsp.readFile(file.abs)
  const hash = crypto.createHash('sha256').update(data).digest('hex')
  const stats = { size: file.size, mtimeMs: file.mtimeMs, hash }

  if (!existing) {
    const moved = db
      .select()
      .from(bookFiles)
      .where(eq(bookFiles.hash, hash))
      .all()
      .find((row) => !onDisk(row.path))
    if (moved) {
      db.transaction((tx) => {
        tx.update(bookFiles)
          .set({ path: file.rel, ...stats })
          .where(eq(bookFiles.id, moved.id))
          .run()
        tx.update(books)
          .set({ missing: false })
          .where(eq(books.id, moved.bookId))
          .run()
      })
      console.log(`[scan] Moved ${moved.path} -> ${file.rel}`)
      return { result: 'moved', bookId: moved.bookId }
    }
  }

  let parsed: ReturnType<typeof readEpub>
  try {
    parsed = readEpub(data)
  } catch (err) {
    console.warn(
      `[scan] Skipping unreadable EPUB ${file.rel}: ${err instanceof Error ? err.message : err}`,
    )
    return { result: 'failed', bookId: existing?.bookId }
  }
  const { metadata, cover } = parsed
  const title =
    metadata.title || path.basename(file.rel, path.extname(file.rel))
  const bookId = existing?.bookId ?? crypto.randomUUID()
  const coverPath = await writeCover(bookId, cover)
  const fields = {
    ...metadata,
    title,
    sortTitle: sortKey(title),
    coverPath,
    missing: false,
  }

  db.transaction((tx) => {
    if (existing) {
      tx.update(books).set(fields).where(eq(books.id, bookId)).run()
      tx.update(bookFiles).set(stats).where(eq(bookFiles.id, existing.id)).run()
    } else {
      tx.insert(books)
        .values({ id: bookId, ...fields })
        .run()
      tx.insert(bookFiles)
        .values({ bookId, path: file.rel, format: 'epub', ...stats })
        .run()
    }
  })
  console.log(`[scan] ${existing ? 'Updated' : 'Added'} ${file.rel}`)
  return { result: existing ? 'updated' : 'added', bookId }
}

// Writes the cover to <data>/covers/<bookId>.<ext>, replacing any previous one.
// Returns its path relative to the data dir.
async function writeCover(bookId: string, cover: EpubCover | null) {
  const dir = path.join(config.dataDir, 'covers')
  await fsp.mkdir(dir, { recursive: true })
  for (const name of await fsp.readdir(dir)) {
    if (name.startsWith(`${bookId}.`)) await fsp.rm(path.join(dir, name))
  }
  if (!cover) return null
  await fsp.writeFile(path.join(dir, `${bookId}.${cover.ext}`), cover.data)
  return `covers/${bookId}.${cover.ext}`
}

// Deletes a book's files from the library, its row (book_files cascade) and its
// scanned and matched covers. Runs in the scan queue so a scan can't re-add it.
export function deleteBook(bookId: string) {
  return serialize(async () => {
    const files = db
      .select({ path: bookFiles.path })
      .from(bookFiles)
      .where(eq(bookFiles.bookId, bookId))
      .all()
    // Files go first: if one can't be removed, the book stays in the library.
    for (const file of files) {
      const abs = resolveInside(config.libraryDir, file.path)
      if (abs) await fsp.rm(abs, { force: true })
    }
    const deleted = db.delete(books).where(eq(books.id, bookId)).run()
    if (!deleted.changes) throw new Error('Book not found')
    const dir = path.join(config.dataDir, 'covers')
    for (const name of await fsp.readdir(dir).catch(() => [])) {
      if (
        name.startsWith(`${bookId}.`) ||
        name.startsWith(`${bookId}-matched.`)
      ) {
        await fsp.rm(path.join(dir, name), { force: true })
      }
    }
    console.log(`[scan] Deleted ${files.map((f) => f.path).join(', ')}`)
  })
}

export class UploadError extends Error {}

// Streams an uploaded EPUB to a temp file in the data dir, reads its metadata,
// then places it at <library>/<Author>/<Title>/<name> (never overwriting) and
// imports it. This and deleteBook are the only places the app changes the library.
export async function uploadBook(
  fileName: string,
  body: WebReadableStream<Uint8Array>,
) {
  const tmpDir = path.join(config.dataDir, 'tmp')
  await fsp.mkdir(tmpDir, { recursive: true })
  const tmp = path.join(tmpDir, `${crypto.randomUUID()}.epub`)
  try {
    await pipeline(Readable.fromWeb(body), fs.createWriteStream(tmp))

    let metadata
    try {
      metadata = readEpub(await fsp.readFile(tmp)).metadata
    } catch {
      throw new UploadError(`${fileName} is not a valid EPUB`)
    }

    const base = path.basename(fileName, path.extname(fileName))
    const dir = path.join(
      config.libraryDir,
      safeSegment(metadata.authors[0] ?? '', 'Unknown Author'),
      safeSegment(metadata.title, safeSegment(base, 'Untitled')),
    )
    await fsp.mkdir(dir, { recursive: true })
    const dest = await placeFile(tmp, dir, safeSegment(base, 'book'))

    const stat = await fsp.stat(dest)
    const file: DiskFile = {
      rel: path.relative(config.libraryDir, dest).split(path.sep).join('/'),
      abs: dest,
      size: stat.size,
      mtimeMs: Math.trunc(stat.mtimeMs),
    }
    const outcome = await serialize(() =>
      importDiskFile(file, (rel) =>
        fs.existsSync(path.join(config.libraryDir, rel)),
      ),
    )
    if (!outcome.bookId) throw new UploadError(`${fileName} could not be read`)
    return { bookId: outcome.bookId, path: file.rel }
  } finally {
    await fsp.rm(tmp, { force: true })
  }
}

// Copies src into dir as <name>.epub, or "<name> (n).epub" if taken. Hard-links when
// possible (atomic, fails if the name exists); data and library are usually
// different volumes, so fall back to an exclusive copy.
async function placeFile(src: string, dir: string, name: string) {
  for (let n = 0; ; n++) {
    const dest = path.join(dir, n ? `${name} (${n}).epub` : `${name}.epub`)
    try {
      await fsp.link(src, dest)
      return dest
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'EEXIST') continue
    }
    try {
      await fsp.copyFile(src, dest, fs.constants.COPYFILE_EXCL)
      return dest
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'EEXIST') continue
      await fsp.rm(dest, { force: true })
      throw err
    }
  }
}

// One path segment from untrusted text: no separators, reserved or control
// characters, leading dots, or trailing dots/spaces (Windows/SMB shares).
function safeSegment(value: string, fallback: string) {
  const cleaned = value
    // oxlint-disable-next-line no-control-regex
    .replace(/[/\\:*?"<>|\u0000-\u001f\u007f]/g, '_')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^[.\s]+|[.\s]+$/g, '')
    .slice(0, 100)
    .trim()
  return cleaned || fallback
}
import { createFileRoute } from '@tanstack/react-router'
import type { ReadableStream as WebReadableStream } from 'node:stream/web'

import { auth } from '#/lib/auth'
import { UploadError, uploadBook } from '#/lib/scanner'

// POST /api/books/upload?name=<file name>, with the raw EPUB as the body (one
// file per request), so it streams to disk instead of being parsed as a form.
export const Route = createFileRoute('/api/books/upload')({
  server: {
    handlers: {
      POST: async ({ request }) => {
        const session = await auth.api.getSession({ headers: request.headers })
        if (!session) return new Response('Unauthorized', { status: 401 })
        if (session.user.role !== 'admin') {
          return new Response('Forbidden', { status: 403 })
        }
        const name = new URL(request.url).searchParams.get('name') ?? ''
        if (!/\.epub$/i.test(name) || !request.body) {
          return new Response('Only EPUB files can be uploaded', {
            status: 400,
          })
        }
        try {
          return Response.json(
            await uploadBook(
              name,
              request.body as WebReadableStream<Uint8Array>,
            ),
          )
        } catch (err) {
          if (err instanceof UploadError) {
            return new Response(err.message, { status: 400 })
          }
          console.error('[upload] Failed:', err)
          return new Response('Upload failed', { status: 500 })
        }
      },
    },
  },
})
// Outbound requests to metadata providers. Every request has a timeout, so a
// slow or offline provider fails on its own instead of hanging the match flow.

const USER_AGENT = 'Bookserve/1.0 (self-hosted ebook server)'
const TIMEOUT_MS = 8_000
const COVER_TIMEOUT_MS = 15_000
const MAX_COVER_BYTES = 10 * 1024 * 1024

export class HttpError extends Error {
  constructor(public status: number) {
    super(`Request failed (HTTP ${status})`)
  }
}

async function request(url: string, timeoutMs: number) {
  try {
    return await fetch(url, {
      headers: { 'user-agent': USER_AGENT },
      signal: AbortSignal.timeout(timeoutMs),
    })
  } catch (err) {
    throw new Error(
      err instanceof Error && err.name === 'TimeoutError'
        ? 'Timed out'
        : 'Could not connect',
    )
  }
}

export async function fetchJson<T>(url: string): Promise<T> {
  const res = await request(url, TIMEOUT_MS)
  if (!res.ok) throw new HttpError(res.status)
  try {
    return (await res.json()) as T
  } catch {
    throw new Error('Invalid response')
  }
}

const SIGNATURES: Array<{ ext: string; matches: (b: Uint8Array) => boolean }> =
  [
    {
      ext: 'jpg',
      matches: (b) => b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff,
    },
    {
      ext: 'png',
      matches: (b) =>
        b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47,
    },
    {
      ext: 'webp',
      matches: (b) => ascii(b, 0, 4) === 'RIFF' && ascii(b, 8, 12) === 'WEBP',
    },
  ]

const ascii = (b: Uint8Array, start: number, end: number) =>
  String.fromCharCode(...b.subarray(start, end))

// Downloads a cover image (jpeg/png/webp only, checked by content type and by
// magic bytes; at most 10 MB). Returns the bytes and a file extension.
export async function downloadCover(url: string) {
  if (!/^https?:\/\//i.test(url)) throw new Error('Invalid cover URL')
  const res = await request(url, COVER_TIMEOUT_MS)
  if (!res.ok || !res.body) throw new HttpError(res.status)
  const type = res.headers.get('content-type') ?? ''
  if (!/^image\/(jpeg|png|webp)\b/i.test(type)) {
    throw new Error('Cover is not a JPEG, PNG or WebP image')
  }
  if (Number(res.headers.get('content-length')) > MAX_COVER_BYTES) {
    throw new Error('Cover is too large')
  }

  const reader = res.body.getReader()
  const chunks: Uint8Array[] = []
  let size = 0
  for (;;) {
    const { done, value } = await reader.read().catch(() => {
      throw new Error('Cover download failed')
    })
    if (done) break
    size += value.byteLength
    if (size > MAX_COVER_BYTES) {
      await reader.cancel().catch(() => {})
      throw new Error('Cover is too large')
    }
    chunks.push(value)
  }

  const data = Buffer.concat(chunks)
  const ext = SIGNATURES.find((s) => s.matches(data))?.ext
  if (!ext) throw new Error('Cover is not a JPEG, PNG or WebP image')
  return { data, ext }
}
import { createServerFn, createServerOnlyFn } from '@tanstack/react-start'
import { getRequestHeaders } from '@tanstack/react-start/server'
import { isAPIError } from 'better-auth/api'
import { count, eq } from 'drizzle-orm'

import { db } from '#/db'
import { user } from '#/db/schema'
import { auth, syntheticEmail } from '#/lib/auth'
import { checkPassword, checkUsername } from '#/lib/credentials'

export type Role = 'admin' | 'user'

// Every admin server function handler starts with this. Pass `headers` on to
// auth.api calls so Better Auth's admin plugin checks the same session.
export const requireAdmin = createServerOnlyFn(async () => {
  const headers = getRequestHeaders()
  const session = await auth.api.getSession({ headers })
  if (session?.user.role !== 'admin') throw new Error('Forbidden')
  return { headers, session }
})

function checkRole(role: string): asserts role is Role {
  if (role !== 'admin' && role !== 'user') throw new Error('Invalid role')
}

function isLastAdmin(userId: string) {
  const target = db
    .select({ role: user.role })
    .from(user)
    .where(eq(user.id, userId))
    .get()
  if (target?.role !== 'admin') return false
  const admins = db
    .select({ n: count() })
    .from(user)
    .where(eq(user.role, 'admin'))
    .get()
  return (admins?.n ?? 0) <= 1
}

// Surface Better Auth's APIError messages as plain errors for the UI.
function rethrow(err: unknown): never {
  // The email is derived from the username, so a taken email means a taken username.
  if (
    isAPIError(err) &&
    err.body?.code === 'USER_ALREADY_EXISTS_USE_ANOTHER_EMAIL'
  ) {
    throw new Error('Username is already taken')
  }
  throw new Error(err instanceof Error ? err.message : 'Request failed')
}

export const listUsers = createServerFn({ method: 'GET' }).handler(async () => {
  const { headers } = await requireAdmin()
  const { users } = await auth.api.listUsers({
    query: { sortBy: 'createdAt' },
    headers,
  })
  // The username plugin's fields are returned at runtime but missing from the type.
  return (users as Array<(typeof users)[number] & { username: string }>).map(
    (u) => ({
      id: u.id,
      username: u.username,
      role: u.role === 'admin' ? 'admin' : 'user',
      createdAt: new Date(u.createdAt).toISOString(),
    }),
  )
})

export const createUser = createServerFn({ method: 'POST' })
  .validator((data: { username: string; password: string; role: string }) => {
    checkUsername(data.username)
    checkPassword(data.password)
    checkRole(data.role)
    return { ...data, role: data.role }
  })
  .handler(async ({ data }) => {
    const { headers } = await requireAdmin()
    await auth.api
      .createUser({
        body: {
          email: syntheticEmail(data.username),
          password: data.password,
          name: data.username,
          role: data.role,
          data: { username: data.username },
        },
        headers,
      })
      .catch(rethrow)
  })

export const setRole = createServerFn({ method: 'POST' })
  .validator((data: { userId: string; role: string }) => {
    checkRole(data.role)
    return { ...data, role: data.role }
  })
  .handler(async ({ data }) => {
    const { headers, session } = await requireAdmin()
    if (data.role === 'user' && isLastAdmin(data.userId)) {
      throw new Error('The last admin cannot be demoted')
    }
    if (data.userId === session.user.id) {
      throw new Error('You cannot change your own role')
    }
    await auth.api
      .setRole({ body: { userId: data.userId, role: data.role }, headers })
      .catch(rethrow)
  })

export const setUserPassword = createServerFn({ method: 'POST' })
  .validator((data: { userId: string; password: string }) => {
    checkPassword(data.password)
    return data
  })
  .handler(async ({ data }) => {
    const { headers } = await requireAdmin()
    await auth.api
      .setUserPassword({
        body: { userId: data.userId, newPassword: data.password },
        headers,
      })
      .catch(rethrow)
  })

export const removeUser = createServerFn({ method: 'POST' })
  .validator((data: { userId: string }) => data)
  .handler(async ({ data }) => {
    const { headers, session } = await requireAdmin()
    if (isLastAdmin(data.userId)) {
      throw new Error('The last admin cannot be deleted')
    }
    if (data.userId === session.user.id) {
      throw new Error('You cannot delete your own account')
    }
    await auth.api
      .removeUser({ body: { userId: data.userId }, headers })
      .catch(rethrow)
  })

import {
  Link,
  Outlet,
  createFileRoute,
  redirect,
  useLocation,
  useRouter,
} from '@tanstack/react-router'
import { ChevronDown, LogOut } from 'lucide-react'

import { Button } from '#/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '#/components/ui/dropdown-menu'
import { authClient } from '#/lib/auth-client'

// Pathless layout: every route under src/routes/_app/ requires a session
// and renders inside the app shell (top bar + page).
export const Route = createFileRoute('/_app')({
  beforeLoad: ({ context }) => {
    if (!context.user) throw redirect({ to: '/login' })
    return { user: context.user }
  },
  component: AppShell,
})

// Top-bar navigation. `admin: true` hides the item from non-admins;
// the route itself must still guard access. `also` marks the item active under
// other path prefixes too (book pages belong to the Library).
const navItems = [
  { to: '/', label: 'Library', exact: true, also: '/books/' },
  { to: '/settings', label: 'Settings', admin: true },
] as const

function AppShell() {
  const { user } = Route.useRouteContext()
  const router = useRouter()
  const pathname = useLocation({ select: (location) => location.pathname })

  async function signOut() {
    await authClient.signOut()
    await router.invalidate()
  }

  return (
    <div className="min-h-screen">
      <header className="border-b">
        <div className="mx-auto flex h-14 max-w-6xl items-center gap-8 px-4">
          <Link to="/" className="font-semibold">
            Bookserve
          </Link>
          <nav className="flex items-center gap-6 text-sm">
            {navItems
              .filter((item) => !('admin' in item) || user.role === 'admin')
              .map((item) => (
                <Link
                  key={item.to}
                  to={item.to}
                  activeOptions={{ exact: 'exact' in item }}
                  data-also-active={
                    'also' in item && pathname.startsWith(item.also)
                      ? true
                      : undefined
                  }
                  className="text-muted-foreground transition-colors hover:text-foreground data-[also-active]:font-medium data-[also-active]:text-foreground data-[status=active]:font-medium data-[status=active]:text-foreground"
                >
                  {item.label}
                </Link>
              ))}
          </nav>
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="sm" className="ml-auto">
                {user.username}
                <ChevronDown />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem onSelect={signOut}>
                <LogOut />
                Sign out
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </header>
      <Outlet />
    </div>
  )
}
import { Link, Outlet, createFileRoute, redirect } from '@tanstack/react-router'

// Admin-only. This guard is for navigation; every settings server function
