import { XMLParser } from 'fast-xml-parser'

import { htmlToText } from '#/lib/epub'
import { HttpError, request } from '#/lib/metadata/http'

// Reads OPDS 1.x catalogs (Atom feeds): navigation entries link to other
// feeds, acquisition entries link to downloadable books. Only EPUB downloads
// are kept, since that is all the library imports.

const FEED_TIMEOUT_MS = 15_000

export type OpdsEntry = {
  id: string
  title: string
  authors: string[]
  summary: string | null
  // Another feed to browse (navigation entries).
  href: string | null
  coverUrl: string | null
  // EPUB acquisition links.
  downloads: Array<{ title: string; href: string }>
}

export type OpdsFeed = {
  url: string
  title: string
  entries: OpdsEntry[]
  next: string | null
  previous: string | null
  searchable: boolean
}

const parser = new XMLParser({
  ignoreAttributes: false,
  attributeNamePrefix: '@_',
  removeNSPrefix: true,
  parseTagValue: false,
  // Content may be (escaped) HTML or XHTML; keep it raw for htmlToText.
  stopNodes: ['*.content', '*.summary'],
  isArray: (name) => ['entry', 'link', 'author', 'Url'].includes(name),
})

type Node = string | ({ '#text'?: string } & Record<string, unknown>)
type Link = { rel: string; type: string; href: string; title: string }

const text = (node: Node | undefined) =>
  (typeof node === 'string' ? node : (node?.['#text'] ?? '')).toString().trim()

const isFeed = (type: string) => type.startsWith('application/atom+xml')

function links(node: { link?: Node[] }, base: string): Link[] {
  return (node.link ?? []).flatMap((l) => {
    if (typeof l !== 'object' || !l['@_href']) return []
    const raw = String(l['@_href'])
    // Search templates hold {placeholders}; resolve them after filling in.
    const href = raw.includes('{') ? raw : resolve(raw, base)
    if (!href) return []
    return [
      {
        rel: String(l['@_rel'] ?? ''),
        type: String(l['@_type'] ?? ''),
        href,
        title: String(l['@_title'] ?? ''),
      },
    ]
  })
}

function resolve(href: string, base: string) {
  try {
    const url = new URL(href, base)
    return ['http:', 'https:', 'data:'].includes(url.protocol)
      ? url.href
      : null
  } catch {
    return null
  }
}

async function fetchXml(url: string) {
  if (!/^https?:\/\//i.test(url)) throw new Error('Invalid URL')
  const res = await request(url, FEED_TIMEOUT_MS)
  if (!res.ok) throw new HttpError(res.status)
  return { url: res.url || url, xml: parser.parse(await res.text()) }
}

function parseEntry(entry: Record<string, unknown>, base: string): OpdsEntry {
  const all = links(entry, base)
  const image =
    all.find((l) => l.rel === 'http://opds-spec.org/image') ??
    all.find((l) => l.rel === 'http://opds-spec.org/image/thumbnail')
  const nav = all.find(
    (l) =>
      isFeed(l.type) &&
      !['related', 'self', 'alternate'].includes(l.rel) &&
      !l.rel.startsWith('http://opds-spec.org/acquisition'),
  )
  const summary = htmlToText(
    text((entry.summary ?? entry.content) as Node | undefined),
  )
  return {
    id: text(entry.id as Node) || nav?.href || text(entry.title as Node),
    title: text(entry.title as Node) || 'Untitled',
    authors: ((entry.author ?? []) as Array<Record<string, Node>>)
      .map((a) => text(a.name))
      .filter(Boolean),
    summary: summary || null,
    href: nav?.href ?? null,
    coverUrl: image?.href ?? null,
    downloads: all
      .filter(
        (l) =>
          l.rel.startsWith('http://opds-spec.org/acquisition') &&
          l.type.startsWith('application/epub+zip') &&
          /^https?:/.test(l.href),
      )
      .map((l) => ({ title: l.title || 'EPUB', href: l.href })),
  }
}

export async function readFeed(url: string): Promise<OpdsFeed> {
  const { url: base, xml } = await fetchXml(url)
  const feed = xml?.feed
  if (!feed) throw new Error('Not an OPDS catalog')
  const feedLinks = links(feed, base)
  const rel = (name: string) =>
    feedLinks.find((l) => l.rel === name && isFeed(l.type))?.href ?? null
  return {
    url: base,
    title: text(feed.title) || 'Catalog',
    entries: ((feed.entry ?? []) as Array<Record<string, unknown>>).map((e) =>
      parseEntry(e, base),
    ),
    next: rel('next'),
    previous: rel('previous') ?? rel('prev'),
    searchable: feedLinks.some((l) => l.rel === 'search'),
  }
}

// Searches through the feed's search link: either an Atom URL template, or an
// OpenSearch description that holds one.
export async function searchFeed(url: string, query: string) {
  const { url: base, xml } = await fetchXml(url)
  const search = links(xml?.feed ?? {}, base).find((l) => l.rel === 'search')
  if (!search) throw new Error('This catalog has no search')

  let template = search.href
  let templateBase = base
  if (!isFeed(search.type)) {
    const osdUrl = resolve(search.href, base)
    if (!osdUrl) throw new Error('This catalog has no search')
    const osd = await fetchXml(osdUrl)
    const urls = (osd.xml?.OpenSearchDescription?.Url ?? []) as Node[]
    const atom = urls.find(
      (u) => typeof u === 'object' && isFeed(String(u['@_type'] ?? '')),
    )
    if (typeof atom !== 'object' || !atom['@_template']) {
      throw new Error('This catalog has no search')
    }
    template = String(atom['@_template'])
    templateBase = osd.url
  }

  const filled = template
    .replace(/\{searchTerms\}/g, encodeURIComponent(query))
    .replace(/\{[^}]*\}/g, '')
  const resultsUrl = resolve(filled, templateBase)
  if (!resultsUrl) throw new Error('This catalog has no search')
  return readFeed(resultsUrl)
}

