// Some catalogs (Project Gutenberg) list books as links to a feed per book,
// which holds the cover and downloads. Open those feeds (a few at a time, and
// cached) and turn each entry whose feed is one book into that book.

const PEEK_TTL_MS = 10 * 60_000
const PEEK_CONCURRENCY = 6
const MAX_PEEKS = 60

type Book = Pick<
  OpdsEntry,
  'title' | 'authors' | 'summary' | 'coverUrl' | 'downloads'
>
const peeks = new Map<string, { at: number; book: Book | null }>()

async function peekBook(href: string): Promise<Book | null> {
  const hit = peeks.get(href)
  if (hit && Date.now() - hit.at < PEEK_TTL_MS) return hit.book
  let feed
  try {
    feed = await readFeed(href)
  } catch {
    return null
  }
  // One book: every entry is an edition of the same title.
  const editions = feed.entries
  const title = editions[0]?.title.toLowerCase()
  const book: Book | null =
    editions.length > 0 &&
    editions.every((e) => e.downloads.length && e.title.toLowerCase() === title)
      ? (() => {
          const downloads = editions
            .flatMap((e) => e.downloads)
            .sort((a, b) => (b.size ?? 0) - (a.size ?? 0))
          const main =
            editions.find((e) => e.downloads.includes(downloads[0])) ??
            editions[0]
          return {
            title: main.title,
            authors: main.authors,
            summary: main.summary,
            coverUrl: editions.find((e) => e.coverUrl)?.coverUrl ?? null,
            downloads,
          }
        })()
      : null
  if (peeks.size > 2000) peeks.clear()
  peeks.set(href, { at: Date.now(), book })
  return book
}

export async function resolveBooks(feed: OpdsFeed) {
