import { useState } from 'react'
import {
  Link,
  createFileRoute,
  redirect,
  useNavigate,
  useRouterState,
} from '@tanstack/react-router'
import {
  Check,
  ChevronLeft,
  ChevronRight,
  Loader2,
  Plus,
  Search,
  Store,
} from 'lucide-react'

import { BookCover } from '#/components/book-cover'
import { Button } from '#/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from '#/components/ui/dialog'
import { Input } from '#/components/ui/input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '#/components/ui/select'
import type { OpdsDownload, OpdsEntry } from '#/lib/opds'
import {
  addFromOpds,
  browseOpds,
  listOpdsServers,
} from '#/lib/opds-functions'
import { cn } from '#/lib/utils'

type MarketSearch = { server?: number; url?: string; q?: string }

// Browses the OPDS servers set up in Settings. `url` is the feed being viewed
// (the server's root when absent) and `q` searches from that feed.
export const Route = createFileRoute('/_app/market')({
  beforeLoad: ({ context }) => {
    if (context.user.role !== 'admin') throw redirect({ to: '/' })
  },
  validateSearch: (search: Record<string, unknown>): MarketSearch => ({
    server: Number(search.server) || undefined,
    url: typeof search.url === 'string' ? search.url : undefined,
    q: typeof search.q === 'string' ? search.q : undefined,
  }),
  loaderDeps: ({ search }) => search,
  loader: async ({ deps }) => {
    const servers = await listOpdsServers()
    const server = servers.find((s) => s.id === deps.server) ?? servers[0]
    if (!server) return { servers, server: null, result: null }
    const result = await browseOpds({
      data: { serverId: server.id, url: deps.url, q: deps.q },
    })
    return { servers, server, result }
  },
  component: Market,
})

function Market() {
  const { servers, server, result } = Route.useLoaderData()
  const search = Route.useSearch()
  const navigate = useNavigate({ from: Route.fullPath })
  const loading = useRouterState({ select: (s) => s.status === 'pending' })

  if (!server) {
    return (
      <main className="mx-auto max-w-6xl px-4 py-8">
        <h1 className="text-2xl font-semibold">Market</h1>
        <div className="mt-6 flex min-h-72 flex-col items-center justify-center gap-3 rounded-lg border border-dashed text-muted-foreground">
          <Store className="size-8" />
          <p className="text-sm">No OPDS servers</p>
          <Button asChild variant="outline" size="sm">
            <Link to="/settings/opds">Add a server</Link>
          </Button>
        </div>
      </main>
    )
  }

  const feed = result?.feed
  const books = feed?.entries.filter((e) => e.downloads.length) ?? []
  const sections = feed?.entries.filter((e) => !e.downloads.length) ?? []
  const atRoot = !search.url && !search.q

  return (
    <main className="mx-auto max-w-6xl px-4 py-8">
      <div className="flex flex-wrap items-center gap-3">
        <h1 className="mr-auto text-2xl font-semibold">Market</h1>
        {servers.length > 1 && (
          <Select
            value={String(server.id)}
            onValueChange={(id) => navigate({ search: { server: Number(id) } })}
          >
            <SelectTrigger aria-label="Server" className="w-full sm:w-52">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {servers.map((s) => (
                <SelectItem key={s.id} value={String(s.id)}>
                  {s.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}
      </div>

      {(feed?.searchable ?? atRoot) && (
        <form
          key={`${server.id} ${search.url} ${search.q}`}
          className="relative mt-6"
          onSubmit={(e) => {
            e.preventDefault()
            const q = String(new FormData(e.currentTarget).get('q')).trim()
            void navigate({
              search: { server: server.id, url: search.url, q: q || undefined },
            })
          }}
        >
          <Search className="pointer-events-none absolute top-1/2 left-4 size-5 -translate-y-1/2 text-muted-foreground" />
          <Input
            type="search"
            name="q"
            placeholder={`Search ${server.name}`}
            aria-label={`Search ${server.name}`}
            defaultValue={search.q}
            className="h-12 rounded-full pl-12 text-base md:text-base"
          />
          {loading && (
            <Loader2 className="absolute top-1/2 right-4 size-5 -translate-y-1/2 animate-spin text-muted-foreground" />
          )}
        </form>
      )}

      <div
        className={cn(
          'mt-8 grid gap-8 transition-opacity',
          loading && 'opacity-50',
        )}
      >
        {!atRoot && (
          <nav className="-mb-2 flex min-w-0 items-center gap-1 text-sm text-muted-foreground">
            <Link
              to="/market"
              search={{ server: server.id }}
              className="shrink-0 hover:text-foreground"
            >
              {server.name}
            </Link>
            {feed && (
              <>
                <ChevronRight className="size-4 shrink-0" />
                <span className="truncate font-medium text-foreground">
                  {feed.title}
                </span>
              </>
            )}
          </nav>
        )}

        {result?.error && (
          <p className="text-sm text-destructive">
            Could not load {server.name}: {result.error}
          </p>
        )}

        {feed && feed.entries.length === 0 && (
          <div className="flex min-h-48 flex-col items-center justify-center gap-3 rounded-lg border border-dashed text-muted-foreground">
            <Search className="size-8" />
            <p className="text-sm">Nothing found</p>
          </div>
        )}

        {sections.length > 0 && (
          <ul className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {sections.map((entry) => (
              <li key={entry.id}>
                <SectionCard entry={entry} serverId={server.id} />
              </li>
            ))}
          </ul>
        )}

        {books.length > 0 && (
          <ul className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5">
            {books.map((entry) => (
              <li key={entry.id}>
                <BookCard entry={entry} />
              </li>
            ))}
          </ul>
        )}

        {(feed?.previous || feed?.next) && (
          <div className="flex items-center justify-center gap-3">
            <Button asChild={!!feed.previous} variant="outline" disabled={!feed.previous}>
              {feed.previous ? (
                <Link
                  to="/market"
                  search={{ server: server.id, url: feed.previous }}
                >
                  <ChevronLeft />
                  Previous
                </Link>
              ) : (
                <span>
                  <ChevronLeft />
                  Previous
                </span>
              )}
            </Button>
            <Button asChild={!!feed.next} variant="outline" disabled={!feed.next}>
              {feed.next ? (
                <Link to="/market" search={{ server: server.id, url: feed.next }}>
                  Next
                  <ChevronRight />
                </Link>
              ) : (
                <span>
                  Next
                  <ChevronRight />
                </span>
              )}
            </Button>
          </div>
        )}
      </div>
    </main>
  )
}

// A category, author, subject or other feed to browse into. Entries with no
// feed and no EPUB (e.g. a PDF-only book) are shown dimmed.
function SectionCard({
  entry,
  serverId,
}: {
  entry: OpdsEntry
  serverId: number
}) {
  const body = (
    <>
      <div className="min-w-0 flex-1">
        <p className="truncate font-medium">{entry.title}</p>
        {(entry.authors.length > 0 || entry.summary) && (
          <p className="mt-0.5 line-clamp-2 text-sm text-muted-foreground">
            {entry.authors.join(', ') || entry.summary}
          </p>
        )}
      </div>
      {entry.href && (
        <ChevronRight className="size-4 shrink-0 text-muted-foreground transition-transform group-hover:translate-x-0.5" />
      )}
    </>
  )
  const className =
    'group flex h-full items-center gap-3 rounded-xl border bg-card px-4 py-3.5'
  if (!entry.href) {
    return <div className={cn(className, 'opacity-60')}>{body}</div>
  }
  return (
    <Link
      to="/market"
      search={{ server: serverId, url: entry.href }}
      className={cn(className, 'transition-colors hover:bg-accent')}
    >
      {body}
    </Link>
  )
}

type AddState =
  | { status: 'idle' | 'adding' }
  | { status: 'added'; bookId: string }
  | { status: 'error'; message: string }

function formatSize(bytes: number | null) {
  if (!bytes) return null
  return bytes >= 1_000_000
    ? `${(bytes / 1_000_000).toFixed(1)} MB`
    : `${Math.max(1, Math.round(bytes / 1000))} KB`
}

// A book in the grid: cover and title open the details; the button adds the
// first (largest) EPUB.
function BookCard({ entry }: { entry: OpdsEntry }) {
  const [open, setOpen] = useState(false)
  const [state, setState] = useState<AddState>({ status: 'idle' })

  async function add(download: OpdsDownload) {
    setState({ status: 'adding' })
    try {
      const { bookId } = await addFromOpds({
        data: { href: download.href, title: entry.title },
      })
      setState({ status: 'added', bookId })
    } catch (err) {
      setState({
        status: 'error',
        message: err instanceof Error ? err.message : 'Download failed',
      })
    }
  }

  return (
    <div className="flex h-full flex-col">
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="group text-left"
      >
        <BookCover
          title={entry.title}
          authors={entry.authors}
          coverUrl={entry.coverUrl}
          className="transition duration-200 group-hover:-translate-y-1 group-hover:shadow-lg"
        />
        <p className="mt-3 line-clamp-2 text-sm leading-snug font-medium">
          {entry.title}
        </p>
        <p className="mt-0.5 line-clamp-1 text-xs text-muted-foreground">
          {entry.authors.join(', ')}
        </p>
      </button>
      <div className="mt-auto pt-3">
        <AddButton
          state={state}
          onAdd={() => add(entry.downloads[0])}
          size="sm"
          className="w-full"
        />
        {state.status === 'error' && (
          <p className="mt-1 text-xs text-destructive">{state.message}</p>
        )}
      </div>
      <BookDialog
        entry={entry}
        open={open}
        onOpenChange={setOpen}
        state={state}
        onAdd={add}
      />
    </div>
  )
}

function AddButton({
  state,
  onAdd,
  size,
  className,
}: {
  state: AddState
  onAdd: () => void
  size?: 'sm' | 'default'
  className?: string
}) {
  if (state.status === 'added') {
    return (
      <Button asChild variant="secondary" size={size} className={className}>
        <Link to="/books/$bookId" params={{ bookId: state.bookId }}>
          <Check />
          In library
        </Link>
      </Button>
    )
  }
  const adding = state.status === 'adding'
  return (
    <Button
      variant={size === 'sm' ? 'outline' : 'default'}
      size={size}
      className={className}
      disabled={adding}
      onClick={onAdd}
    >
      {adding ? <Loader2 className="animate-spin" /> : <Plus />}
      {adding ? 'Adding…' : 'Add to library'}
    </Button>
  )
}

function BookDialog({
  entry,
  open,
  onOpenChange,
  state,
  onAdd,
}: {
  entry: OpdsEntry
  open: boolean
  onOpenChange: (open: boolean) => void
  state: AddState
  onAdd: (download: OpdsDownload) => void
}) {
  const [href, setHref] = useState(entry.downloads[0].href)
  const download =
    entry.downloads.find((d) => d.href === href) ?? entry.downloads[0]
  const label = (d: OpdsDownload) =>
    [d.title, formatSize(d.size)].filter(Boolean).join(' · ')

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl">
        <div className="grid gap-6 sm:grid-cols-[180px_1fr]">
          <BookCover
            title={entry.title}
            authors={entry.authors}
            coverUrl={entry.coverUrl}
            className="mx-auto w-40 sm:w-full"
          />
          <div className="flex min-w-0 flex-col gap-4">
            <div className="grid gap-1 pr-6">
              <DialogTitle className="text-xl leading-tight">
                {entry.title}
              </DialogTitle>
              <DialogDescription>{entry.authors.join(', ')}</DialogDescription>
            </div>
            {entry.downloads.length > 1 && (
              <Select value={download.href} onValueChange={setHref}>
                <SelectTrigger aria-label="Format" className="w-full">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {entry.downloads.map((d) => (
                    <SelectItem key={d.href} value={d.href}>
                      {label(d)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}
            <div className="flex flex-wrap items-center gap-3">
              <AddButton state={state} onAdd={() => onAdd(download)} />
              {entry.downloads.length === 1 && formatSize(download.size) && (
                <span className="text-sm text-muted-foreground">
                  {formatSize(download.size)}
                </span>
              )}
            </div>
            {state.status === 'error' && (
              <p className="text-sm text-destructive">{state.message}</p>
            )}
            {entry.summary && (
              <p className="text-sm leading-relaxed whitespace-pre-line text-muted-foreground">
                {entry.summary}
              </p>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}

