import { defineIntegration } from '#/lib/market/sdk'
import type {
  BookSummary,
  IntegrationContext,
  Listing,
  ShelfLink,
} from '#/lib/market/sdk'
import { parseFeed } from '#/lib/market/opds'
import type { OpdsEntry } from '#/lib/market/opds'

// Project Gutenberg, through its official OPDS catalog, with Gutenberg's
// quirks smoothed over: lists link to a feed per book, so covers come from
// Gutenberg's predictable cover URLs; a book's feed has one entry per build
// (with and without images), merged into one book; descriptions come from the
// "Summary:" field; audiobooks have no EPUB.

const BASE = 'https://www.gutenberg.org'
const CACHE_MS = 10 * 60_000

const ROWS = [
  { id: 'popular', title: 'Popular', path: '/ebooks/search.opds/?sort_order=downloads' },
  { id: 'latest', title: 'Latest', path: '/ebooks/search.opds/?sort_order=release_date' },
]

// Cleaner names for Gutenberg's EPUB builds (the id is the URL suffix).
const FORMAT_LABELS: Record<string, string> = {
  'epub3.images': 'EPUB 3 with images',
  'epub.images': 'EPUB 2 with images (older e-readers)',
  'epub.noimages': 'EPUB 2 without images (older e-readers)',
}

const bookPath = (id: string) => `/ebooks/${id}.opds`
const coverUrl = (id: string) =>
  `${BASE}/cache/epub/${id}/pg${id}.cover.medium.jpg`

// A path on gutenberg.org from a shelf id or cursor; rejects anything else.
function gutenbergPath(value: string) {
  const url = new URL(value, BASE)
  if (url.origin !== BASE || !url.pathname.startsWith('/ebooks/')) {
    throw new Error('Unknown shelf')
  }
  return url.pathname + url.search
}

function feed(ctx: IntegrationContext, path: string) {
  return ctx.cached(path, CACHE_MS, async () => {
    const res = await ctx.fetch(BASE + path)
    return parseFeed(await res.text(), res.url || BASE + path)
  })
}

async function listing(
  ctx: IntegrationContext,
  path: string,
  title?: string,
): Promise<Listing> {
  const f = await feed(ctx, path)
  const books: BookSummary[] = []
  const shelves: ShelfLink[] = []
  for (const entry of f.entries) {
    const id = entry.href?.match(/^https:\/\/www\.gutenberg\.org\/ebooks\/(\d+)\.opds$/)?.[1]
    if (id) {
      // In lists, the entry's content is the author line.
      books.push({
        id,
        title: entry.title,
        authors: entry.summary ? [entry.summary] : [],
        coverUrl: coverUrl(id),
      })
    } else if (entry.href?.startsWith(`${BASE}/ebooks/`)) {
      // Authors, subjects and other lists; links off-site are dropped.
      shelves.push({
        id: gutenbergPath(entry.href),
        title: entry.title,
        description: entry.summary,
      })
    }
  }
  return {
    title: title ?? f.title,
    shelves,
    books,
    nextCursor: f.next?.startsWith(`${BASE}/ebooks/`)
      ? gutenbergPath(f.next)
      : null,
  }
}

// The builds in a book's feed, largest first (the one with images).
async function builds(ctx: IntegrationContext, id: string) {
  if (!/^\d+$/.test(id)) throw new Error('Unknown book')
  const { entries } = await feed(ctx, bookPath(id))
  if (!entries.length) throw new Error('Unknown book')
  const largest = (e: OpdsEntry) =>
    Math.max(0, ...e.downloads.map((d) => d.size ?? 0))
  return [...entries].sort((a, b) => largest(b) - largest(a))
}

const formatId = (id: string, href: string) =>
  href.startsWith(`${BASE}/ebooks/${id}.`)
    ? href.slice(`${BASE}/ebooks/${id}.`.length)
    : null

export const gutenberg = defineIntegration({
  id: 'gutenberg',
  name: 'Project Gutenberg',
  apiVersion: 1,
  settings: [],

  async home(ctx) {
    const rows = await Promise.all(
      ROWS.map(async (row) => ({
        id: row.id,
        title: row.title,
        description: null,
        books: (await listing(ctx, row.path)).books,
      })),
    )
    return {
      rows,
      shelves: [
        {
          id: '/ebooks/search.opds/?sort_order=random',
          title: 'Random',
          description: 'A random selection of books',
        },
      ],
    }
  },

  shelf(ctx, shelfId, cursor) {
    const row = ROWS.find((r) => r.id === shelfId)
    return listing(
      ctx,
      gutenbergPath(cursor ?? row?.path ?? shelfId),
      row?.title,
    )
  },

  search(ctx, query, cursor) {
    return listing(
      ctx,
      cursor
        ? gutenbergPath(cursor)
        : `/ebooks/search.opds/?query=${encodeURIComponent(query)}`,
    )
  },

  async book(ctx, id) {
    const [main, ...rest] = await builds(ctx, id)
    const summary = main.summary?.match(
      /(?:^|\n)Summary:\n([\s\S]*?)(?:\n\n|$)/,
    )?.[1]
    const formats = [main, ...rest]
      .flatMap((e) => e.downloads)
      .flatMap((d) => {
        const fid = formatId(id, d.href)
        return fid
          ? [{ id: fid, label: FORMAT_LABELS[fid] ?? d.title, size: d.size }]
          : []
      })
    return {
      id,
      title: main.title,
      authors: main.authors,
      coverUrl: main.coverUrl ?? coverUrl(id),
      description: summary?.trim() || null,
      language: main.language,
      // Gutenberg's dates are its own release dates, not publication dates.
      publisher: null,
      publishedDate: null,
      isbn: null,
      subjects: main.subjects,
      formats,
    }
  },

  async download(ctx, id, fid) {
    const entries = await builds(ctx, id)
    const ok = entries.some((e) =>
      e.downloads.some((d) => formatId(id, d.href) === fid),
    )
    if (!ok) throw new Error('Unknown format')
    return { url: `${BASE}/ebooks/${id}.${fid}` }
  },
})

