input.content:
# Market integrations

The Market lets admins browse online catalogs and add books to the library. Each catalog type is an **integration**: a small module that fetches the catalog and maps it into Bookserve's types. Bookserve owns everything else: the store UI, caching, validation, downloading, EPUB checks, provenance and metadata.

An admin adds **sources** in Settings → Market sources. A source is an integration plus its settings (for example, an OPDS catalog URL and credentials), with its own id. Books added from a source are linked to it in `book_sources`.

Built-in integrations:

- `gutenberg`: Project Gutenberg (`src/lib/market/integrations/gutenberg.ts`). Seeded as the default source.
- `opds`: any OPDS 1.x catalog (`src/lib/market/integrations/opds.ts`).

## Writing an integration

An integration is a `MarketIntegration` object from `src/lib/market/sdk.ts`, the only module it needs from Bookserve (plus, optionally, the OPDS parser in `src/lib/market/opds.ts`).

```ts
import { defineIntegration } from '#/lib/market/sdk'

export const example = defineIntegration({
  id: 'example', // stored on sources and book_sources; never change it
  name: 'Example Books',
  apiVersion: 1,
  // Fields the admin fills in when adding a source; read them from ctx.settings.
  settings: [{ key: 'apiKey', label: 'API key', type: 'password', required: true }],

  // Optional: called when a source is added. Throw to reject the settings.
  async check(ctx) {
    await ctx.fetch('https://example.com/api/me', { headers: auth(ctx) })
  },

  // The landing page: rows of books, and shelves (categories) to browse.
  async home(ctx) {
    return {
      rows: [{ id: 'popular', title: 'Popular', description: null, books: [] }],
      shelves: [{ id: 'fiction', title: 'Fiction', description: null }],
    }
  },

  // A shelf, row or any id you returned in a ShelfLink; `cursor` is the
  // nextCursor you returned for the previous page.
  async shelf(ctx, shelfId, cursor) {
    return { title: 'Fiction', shelves: [], books: [], nextCursor: null }
  },

  // Optional; without it there is no search box.
  async search(ctx, query, cursor) {
    return { title: query, shelves: [], books: [], nextCursor: null }
  },

  async book(ctx, bookId) {
    return {
      id: bookId,
      title: '…',
      authors: ['…'],
      coverUrl: null,
      description: null,
      language: 'en',
      publisher: null,
      publishedDate: null,
      isbn: null,
      subjects: [],
      shelves: [], // related shelves: the author, series, categories
      formats: [{ id: 'epub', label: 'EPUB', size: null }], // EPUB only, best first
    }
  },

  // Where to download a format. Bookserve streams it into the library.
  async download(ctx, bookId, formatId) {
    return { url: `https://example.com/books/${bookId}.epub`, headers: auth(ctx) }
  },
})
```

Then register it in `INTEGRATIONS` in `src/lib/market/host.ts`. It shows up in the "Add source" dialog, with a form built from `settings`.

## Rules

- **Ids are yours.** Book, shelf, format ids and cursors are opaque strings that Bookserve passes back unchanged. Book ids must be stable: they are stored in `book_sources.external_id` to show "In library" and to avoid adding a book twice. They arrive from the browser, so validate them before building URLs (see `catalogPath` in the Gutenberg integration).
- **Use `ctx.fetch`**, not `fetch`: it adds a timeout and Bookserve's User-Agent, and throws on network errors and non-2xx responses with a message the UI shows as is. Throw an `Error` with a short message for anything else ("Unknown book").
- **Use `ctx.cached(key, ttlMs, load)`** for anything `book()` and `download()` refetch. Its cache is per source and in memory.
- **Return plain data.** Text is plain (no HTML; `htmlToText` from `#/lib/epub` converts). Dates are `YYYY`, `YYYY-MM` or `YYYY-MM-DD`. Cover URLs are http(s). Bookserve trims and drops anything malformed (`src/lib/market/host.ts`), so a buggy integration can't break the page.
- **EPUB only.** List only EPUB formats; return an empty `formats` list for books without one. The download is checked to be a valid EPUB before it is added.
- **Don't fill in metadata you don't have.** When a book is added, its EPUB's own metadata wins; the integration's description, language, publisher, date, ISBN and cover only fill gaps (stored as a match in `books.matched`, so "Revert to file metadata" removes them).
- **Trust.** Integrations run in the server process with full access, so only add code you trust. Settings of type `password` are never sent to the browser.
- **Versioning.** `apiVersion` is `1`. A breaking change to the SDK bumps it, and integrations with another version are not loaded.

import type { BookSummary, ShelfLink } from '#/lib/market/sdk'

// Merges results from several sources into one list, deduplicating books
// that are the same work. Client-safe, so "Load more" merges the same way.

// A source's id for a book or shelf.
export type SourceRef = { source: number; id: string }

export type Offer = SourceRef & { sourceName: string }

export type MergedBook = Omit<BookSummary, 'id'> & { offers: Offer[] }

export type MergedShelf = {
  title: string
  description: string | null
  refs: SourceRef[]
}

export type SourceResults<T> = {
  source: number
  sourceName: string
  items: T[]
}

const fold = (text: string) =>
  text
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()

// "The Adventures of Sherlock Holmes: Illustrated" → "adventures of sherlock holmes"
function workTitle(title: string) {
  return fold(title)
    .split(/\s*[:;([]\s*|\s+-{1,2}\s+/)[0]
    .replace(/&/g, ' and ')
    .replace(/^(the|a|an)\s+/, '')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim()
}

// "Jane Austen" → "austen"; "Austen, Jane" → "austen".
function surname(author: string) {
  const name = fold(author)
  const last = name.includes(',') ? name.split(',')[0] : name.split(/\s+/).at(-1)
  return (last ?? '').replace(/[^\p{L}\p{N}]+/gu, '')
}

function isbn13(isbn: string | null | undefined) {
  const digits = (isbn ?? '').replace(/[^\dX]/gi, '').toUpperCase()
  if (digits.length === 13) return digits
  if (digits.length !== 10) return null
  const core = `978${digits.slice(0, 9)}`
  const sum = [...core].reduce(
    (total, d, i) => total + Number(d) * (i % 2 ? 3 : 1),
    0,
  )
  return core + ((10 - (sum % 10)) % 10)
}

// The keys under which two books count as the same work. Books without an
// author only match by ISBN: "Poems" by two people isn't one book.
export function bookKeys(book: Pick<BookSummary, 'title' | 'authors' | 'isbn'>) {
  const keys: string[] = []
  const isbn = isbn13(book.isbn)
  if (isbn) keys.push(`isbn:${isbn}`)
  const title = workTitle(book.title)
  const author = book.authors[0] ? surname(book.authors[0]) : ''
  if (title && author) keys.push(`work:${title}|${author}`)
  return keys
}

// Interleaves each source's ranked list (1st of each, then 2nd of each...).
function interleave<T>(lists: Array<SourceResults<T>>) {
  const out: Array<{ list: SourceResults<T>; item: T }> = []
  const longest = Math.max(0, ...lists.map((l) => l.items.length))
  for (let i = 0; i < longest; i++) {
    for (const list of lists) {
      if (i < list.items.length) out.push({ list, item: list.items[i] })
    }
  }
  return out
}

// Appends each source's books to `existing`, merging a book into an earlier
// one with a shared key, unless that one already has a copy from the same
// source (then they are different editions and stay apart).
export function mergeBooks(
  existing: MergedBook[],
  lists: Array<SourceResults<BookSummary>>,
) {
  const merged = existing.map((b) => ({ ...b, offers: [...b.offers] }))
  const keys = merged.map((b) => new Set(bookKeys(b)))
  for (const { list, item } of interleave(lists)) {
    if (merged.some((b) => b.offers.some((o) => o.source === list.source && o.id === item.id))) {
      continue
    }
    const offer = { source: list.source, sourceName: list.sourceName, id: item.id }
    const itemKeys = bookKeys(item)
    const index = merged.findIndex(
      (b, i) =>
        !b.offers.some((o) => o.source === list.source) &&
        itemKeys.some((k) => keys[i].has(k)),
    )
    if (index < 0) {
      merged.push({
        title: item.title,
        authors: item.authors,
        coverUrl: item.coverUrl,
        isbn: item.isbn ?? null,
        offers: [offer],
      })
      keys.push(new Set(itemKeys))
      continue
    }
    const book = merged[index]
    book.offers.push(offer)
    book.coverUrl ??= item.coverUrl
    book.isbn ??= item.isbn ?? null
    for (const key of itemKeys) keys[index].add(key)
  }
  return merged
}

// Merges shelves (and home rows) with the same name across sources.
export function mergeShelves(lists: Array<SourceResults<ShelfLink>>) {
  const merged: MergedShelf[] = []
  for (const { list, item } of interleave(lists)) {
    const name = fold(item.title).replace(/[^\p{L}\p{N}]+/gu, ' ').trim()
    const shelf = merged.find(
      (s) =>
        fold(s.title).replace(/[^\p{L}\p{N}]+/gu, ' ').trim() === name &&
        !s.refs.some((r) => r.source === list.source),
    )
    const ref = { source: list.source, id: item.id }
    if (shelf) {
      shelf.refs.push(ref)
      shelf.description ??= item.description
    } else {
      merged.push({
        title: item.title,
        description: item.description,
        refs: [ref],
      })
    }
  }
  return merged
}

