// One home from every source's: rows with the same name merge (and so do
// their books), as do shelves.
export function mergeHome(
  homes: Array<{
    source: number
    sourceName: string
    rows: Array<ShelfLink & { books: BookSummary[] }>
    shelves: ShelfLink[]
  }>,
) {
  const rows = mergeShelves(
    homes.map((h) => ({ ...h, items: h.rows })),
  ).map((row) => ({
    ...row,
    books: mergeBooks(
      [],
      row.refs.map((ref) => {
        const home = homes.find((h) => h.source === ref.source)!
        return {
          source: ref.source,
          sourceName: home.sourceName,
          items: home.rows.find((r) => r.id === ref.id)?.books ?? [],
        }
      }),
    ),
  }))
  const shelves = mergeShelves(homes.map((h) => ({ ...h, items: h.shelves })))
  return { rows, shelves }
}
