        (err) => current && update(s.id, { loading: false, error: message(err) }),
      )
    }
    return () => {
      current = false
    }
    // `key` covers the search; sources only change on reload.
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [key, sources])

  // The next page from every source that has one. A source that fails keeps
  // its cursor, so "Load more" retries it.
  function loadMore() {
    for (const r of results.filter((r) => r.cursor && !r.loading)) {
      update(r.source, { loading: true, error: null })
      const ref = search.shelf?.find((s) => s.source === r.source)
      marketBrowse({
        data: {
          sourceId: r.source,
          q: search.q,
          shelf: ref?.id,
          cursor: r.cursor!,
        },
      }).then(
        (view) => {
          if (view.kind !== 'listing') return
          remember(r.source, view.inLibrary)
          setResults((prev) =>
            prev.map((p) =>
              p.source === r.source
                ? {
                    ...p,
                    loading: false,
                    pages: [...p.pages, view.listing],
                    cursor: view.listing.nextCursor,
                  }
                : p,
            ),
          )
        },
        (err) => update(r.source, { loading: false, error: message(err) }),
      )
    }
  }

  return {
    results,
    inLibrary,
    loadMore,
    markAdded: (offer: SourceRef, bookId: string) =>
      remember(offer.source, { [`${offer.source}:${offer.id}`]: bookId }),
  }
}

